{
  "missing_information": [
    {
      "category": "Inventory Tracking Method",
      "gap": "It is unclear how supplies are currently monitored — whether by visual inspection, a written list, a spreadsheet, or a digital inventory tool.",
      "why_it_matters": "The tracking method determines whether automated stock-level monitoring or alerts are feasible and what data already exists."
    },
    {
      "category": "Reorder Trigger",
      "gap": "There is no defined threshold or rule for when a supply is considered 'low' and triggers an order.",
      "why_it_matters": "A precise reorder point is essential for automating replenishment decisions and avoiding both stockouts and overstocking."
    },
    {
      "category": "Supplier and Ordering Channel",
      "gap": "The process for placing an order is not described — whether it is done through an online retailer, a subscription service, a physical store, or another channel.",
      "why_it_matters": "The ordering channel determines whether the purchase step can be automated or integrated with an existing platform."
    },
    {
      "category": "Supply Item Scope",
      "gap": "The types and number of distinct supply items managed are not specified (e.g., diapers, formula, wipes, medications).",
      "why_it_matters": "The variety and volume of items affects the complexity of tracking, ordering rules, and storage organisation."
    },
    {
      "category": "Delivery Handling Steps",
      "gap": "The actions taken when a delivery arrives are described only as 'put everything away,' with no detail on checking quantities, verifying the order, or updating stock records.",
      "why_it_matters": "Unspecified receiving steps may hide quality checks or discrepancy resolution that are important for process accuracy and automation."
    },
    {
      "category": "Frequency and Regularity",
      "gap": "There is no information on how often stock checks are performed or whether ordering follows a fixed schedule or is purely demand-driven.",
      "why_it_matters": "Frequency and scheduling patterns influence whether a time-based or event-based automation approach is more appropriate."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "How do you currently keep track of which supplies are running low — for example, do you rely on visual checks, a written list, a spreadsheet, or any kind of app or tool?",
      "targets": ["Inventory Tracking Method"]
    },
    {
      "id": "Q2",
      "question": "At what point do you decide a supply needs to be reordered — is there a specific quantity remaining, a number of days' worth left, or is it more of a judgment call each time?",
      "targets": ["Reorder Trigger"]
    },
    {
      "id": "Q3",
      "question": "Where and how do you place the order when a supply is low — for instance, through an online store, a subscription service, or by going to a physical shop?",
      "targets": ["Supplier and Ordering Channel"]
    },
    {
      "id": "Q4",
      "question": "Can you list the main types of supplies you manage, and roughly how many distinct items are involved in this process?",
      "targets": ["Supply Item Scope"]
    },
    {
      "id": "Q5",
      "question": "When a delivery arrives, do you do anything beyond putting items away — such as checking that the quantities match the order or noting the new stock level somewhere?",
      "targets": ["Delivery Handling Steps"]
    },
    {
      "id": "Q6",
      "question": "Do you check stock levels on a regular schedule, such as weekly, or do you only look when you happen to notice something is running out?",
      "targets": ["Frequency and Regularity"]
    }
  ]
}
